import{_ as o,o as a,c as r,b3 as n}from"./chunks/framework.VnelH-cX.js";const s="/docs-imgs/faq/SnowShot_2025-10-28_05-09-04.webp",e="/docs-imgs/faq/SnowShot_2025-10-28_05-14-17.webp",h=JSON.parse('{"title":"截图卡顿，绘制时反应迟钝、存在延迟","description":"","frontmatter":{},"headers":[],"relativePath":"faq/common/1.md","filePath":"faq/common/1.md","lastUpdated":1786700458000}'),i={name:"faq/common/1.md"};function p(_,t,c,g,d,l){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="截图卡顿-绘制时反应迟钝、存在延迟" tabindex="-1">截图卡顿，绘制时反应迟钝、存在延迟 <a class="header-anchor" href="#截图卡顿-绘制时反应迟钝、存在延迟" aria-label="Permalink to &quot;截图卡顿，绘制时反应迟钝、存在延迟&quot;">​</a></h1><p>绘制延迟往往是渲染时的计算资源消耗过高，可以通过关闭部分功能来提高渲染性能。</p><h2 id="禁用选区过渡动画" tabindex="-1">禁用选区过渡动画 <a class="header-anchor" href="#禁用选区过渡动画" aria-label="Permalink to &quot;禁用选区过渡动画&quot;">​</a></h2><p>在 Wing Shot 主界面查看侧边栏点击<strong>设置</strong>下的<strong>界面设置</strong>，找到<strong>截图</strong>下的<strong>禁用动画</strong>选项。</p><p>点击选项，切换到<strong>启用</strong>状态。</p><p><img src="'+s+'" alt="禁用动画"></p><h2 id="关闭多显示截图" tabindex="-1">关闭多显示截图 <a class="header-anchor" href="#关闭多显示截图" aria-label="Permalink to &quot;关闭多显示截图&quot;">​</a></h2><p>跨屏截图是个不常用的功能，对于常见的笔记本设备，额外的扩展屏幕在画面渲染时需要消耗非常多的资源。关闭多显示器截图后可以显著改善操作延迟的问题。</p><p>在 Wing Shot 主界面查看侧边栏点击<strong>设置</strong>下的<strong>系统设置</strong>，找到<strong>截图</strong>下的<strong>启用多显示截图</strong>选项。</p><p><img src="'+e+'" alt="关闭多显示截图"></p>',10)])])}const f=o(i,[["render",p]]);export{h as __pageData,f as default};
